pou.interface:
{implicit on}
FUNCTION string__to__wstring : WSTRING(255)
VAR_INPUT
	in: STRING(255);
END_VAR
VAR
	i : INT := 0;
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
WHILE (in[i] <> 0 AND i < 255) DO
	string__to__wstring[i] := in[i];
	i := i+1;
END_WHILE
string__to__wstring[i] := 0;		
{implicit off}

pou.interface:
{implicit on}
FUNCTION wstring__to__string : STRING(255)
VAR_INPUT
	in: WSTRING(255);
END_VAR
VAR
	i : INT := 0;
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
WHILE (in[i] <> 0 AND i < 255) DO
	wstring__to__string[i] := WORD_TO_BYTE(in[i]);
	i := i+1;
END_WHILE

wstring__to__string[i] := 0;		
{implicit off}
